import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.DCaeQ2Kp.js";const s=JSON.parse('{"title":"配置（MOMO_*）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/config.md","filePath":"guide/config.md"}'),r={name:"guide/config.md"};function a(_,t,O,h,M,n){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="配置-momo" tabindex="-1">配置（MOMO_*） <a class="header-anchor" href="#配置-momo" aria-label="Permalink to &quot;配置（MOMO_*）&quot;">​</a></h1><p>所有运行参数走 <code>MOMO_</code> 前缀环境变量；<code>.env</code> 仅本地，仓内只有占位 <code>.env.example</code>。新增 env 键必须同步三处：<code>.env.example</code>、<code>config.md</code>、实现代码。</p><h2 id="端点" tabindex="-1">端点 <a class="header-anchor" href="#端点" aria-label="Permalink to &quot;端点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>MOMO_ORCH_LISTEN</code></td><td><code>127.0.0.1:7800</code></td><td>momod WS + 静态托管</td></tr><tr><td><code>MOMO_UI_DIR</code></td><td><code>./web/dist</code></td><td>前端静态目录</td></tr><tr><td><code>MOMO_LLM_ENDPOINT</code></td><td><code>http://mac-studio.local:7820/v1</code></td><td>大脑 OpenAI-compat base URL</td></tr><tr><td><code>MOMO_LLM_MODEL</code></td><td><code>qwen3-30b-a3b-4bit</code></td><td>传给大脑的 model 字段</td></tr><tr><td><code>MOMO_LLM_API_KEY</code></td><td>空</td><td><strong>敏感</strong>；DeepSeek 档必填</td></tr><tr><td><code>MOMO_ASR_ENDPOINT</code></td><td><code>ws://127.0.0.1:7810/ws</code></td><td>ASR 服务</td></tr><tr><td><code>MOMO_TTS_ENDPOINT</code></td><td><code>ws://127.0.0.1:7811/ws</code></td><td>TTS 服务</td></tr><tr><td><code>MOMO_EMBED_ENDPOINT</code></td><td><code>ws://127.0.0.1:7812/ws</code></td><td>记忆检索（P3）</td></tr></tbody></table><h2 id="模型与声线" tabindex="-1">模型与声线 <a class="header-anchor" href="#模型与声线" aria-label="Permalink to &quot;模型与声线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>MOMO_MODELS_DIR</code></td><td><code>~/.cache/momo/models</code></td><td>权重根目录</td></tr><tr><td><code>MOMO_TTS_PROVIDER</code></td><td><code>kokoro</code></td><td>edge / kokoro / cosyvoice3 / sovits / f5</td></tr><tr><td><code>MOMO_TTS_MODEL_DIR</code></td><td>—</td><td>SFT 产物目录（声线切换=改它）</td></tr><tr><td><code>MOMO_TTS_VOICE_REF</code></td><td>—</td><td>零样本参考音</td></tr><tr><td><code>MOMO_PROFILE</code></td><td><code>normal</code></td><td>normal / degraded</td></tr></tbody></table><h2 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>MOMO_IDLE_TIMEOUT_S</code></td><td><code>20</code></td><td>自发开口计时，0=关闭</td></tr><tr><td><code>MOMO_BARGEIN_MIN_MS</code></td><td><code>250</code></td><td>打断防抖</td></tr><tr><td><code>MOMO_SENT_SOFT_CHARS</code> / <code>MOMO_SENT_MAX_CHARS</code></td><td><code>25</code> / <code>60</code></td><td>句切软/硬上限</td></tr></tbody></table><h2 id="运维与其他" tabindex="-1">运维与其他 <a class="header-anchor" href="#运维与其他" aria-label="Permalink to &quot;运维与其他&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>MOMO_DATA_COLLECTION</code></td><td><code>off</code></td><td>会话采集开关（人格轨道数据源）</td></tr><tr><td><code>MOMO_DATA_KEEP_AUDIO</code></td><td><code>off</code></td><td>原始麦音频落盘（敏感产物）</td></tr><tr><td><code>MOMO_WEB_TOKEN</code></td><td>空</td><td><strong>敏感</strong>；<code>momoctl web --listen</code> 出 localhost 时必填</td></tr><tr><td><code>MOMO_DEEPSEEK_API_KEY</code></td><td>空</td><td><strong>敏感</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">权威来源</p><p><a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/config.md" target="_blank" rel="noreferrer">momo-docs/01-architecture/config.md</a> — 全量键表、degraded 覆盖样例、敏感清单。</p></div>',11)])])}const l=d(r,[["render",a]]);export{s as __pageData,l as default};
